package com.procurement.quotationcomparison.controller;import com.procurement.common.response.*;import com.procurement.quotationcomparison.dto.response.*;import com.procurement.quotationcomparison.service.*;import org.springframework.data.domain.*;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/quotation-comparison-lines")public class QuotationComparisonLineController{private final QuotationComparisonService s;public QuotationComparisonLineController(QuotationComparisonService s){this.s=s;}@GetMapping public ApiResponse<PageResponse<QuotationComparisonLineResponse>>search(@RequestParam(required=false)Long comparisonId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.success(s.lines(comparisonId,PageRequest.of(page,size,Sort.by(Sort.Direction.ASC,"rank"))));}@GetMapping("/search")public ApiResponse<PageResponse<QuotationComparisonLineResponse>>searchAlias(@RequestParam(required=false)Long comparisonId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return search(comparisonId,page,size);}@GetMapping("/{id}")public ApiResponse<QuotationComparisonLineResponse>get(@PathVariable Long id){return ApiResponse.success(s.line(id));}}
